pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address nonOwner, address receiver, uint256 amount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(c));
        vm.assume(nonOwner.balance == 0);
        bool ok;
        vm.prank(nonOwner);
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "non-owner must not succeed");
    }
}
